def validate(v,s,path='"'$'"'):
 typ=s.get('type')
 if typ=='object':
  assert isinstance(v,dict),path
  assert set(s.get('required',[])) <= set(v),path
  if s.get('additionalProperties') is False: assert set(v)<=set(s.get('properties',{})),path
  for k,x in v.items():
   if k in s.get('properties',{}): validate(x,s['properties'][k],path+'.'+k)
 elif typ=='array':
  assert isinstance(v,list) and len(v)>=s.get('minItems',0),path
  for i,x in enumerate(v):validate(x,s.get('items',{}),path+f'[{i}]')
 elif typ=='string':assert isinstance(v,str) and len(v)>=s.get('minLength',0),path
 if 'enum' in s: assert v in s['enum'],path
 if 'const' in s: assert v==s['const'] and type(v)==type(s['const']),path
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
known=set(r['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=known
assert p['parent_trial'] in known
assert all(c['parent_ref'] in known for c in p['study']['contrasts'])
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
parent=ast.parse(open('history_g0_r0049_block_retrieval_transfer.py').read())
def methods(tree):
 return {n.name:n for c in tree.body if isinstance(c,ast.ClassDef) for n in c.body if isinstance(n,ast.FunctionDef)}
pm=methods(parent)
normalized=[]
for v in p['variants']:
 assert set(v)=={'name','file','role','config','note'}
 assert v['file']==os.path.basename(v['file']) and v['file'].endswith('.py')
 assert v['role'] in ('candidate','control')
 tree=ast.parse(open(v['file']).read());mm=methods(tree)
 literal=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))
 assert literal==v['config']
 init=mm['__init__']
 defaults=dict(zip([a.arg for a in init.args.args][-len(init.args.defaults):],init.args.defaults))
 for k,x in v['config'].items():
  y=ast.literal_eval(defaults[k]);assert (list(y) if isinstance(y,tuple) else y)==x,(v['name'],k,y,x)
 assert mm.keys()==pm.keys()
 for k in mm:
  if k not in ('__init__','forward','_context_history_correction'):
   assert ast.dump(mm[k])==ast.dump(pm[k]),(v['name'],k)
 calls=lambda node:[ast.dump(n) for n in ast.walk(node) if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and isinstance(n.func.value,ast.Name) and n.func.value.id=='nn']
 assert calls(init)==calls(pm['__init__']),v['name']
 allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(a.name.split('.')[0] in allowed for a in n.names)
  if isinstance(n,ast.ImportFrom):assert n.module.split('.')[0] in allowed
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'open','exec','eval','compile','__import__','input'}
 # Normalize only the literal config and two declared constructor factors.
 for n in tree.body:
  if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets):n.value=ast.Constant(value=None)
 args=mm['__init__'].args
 for i,a in enumerate(args.args[-len(args.defaults):]):
  if a.arg in ('retrieval_key_source','block_aux_adapter_context_grad'):args.defaults[i]=ast.Constant(value=None)
 normalized.append(ast.dump(tree))
 print(v['file'],'sha256',hashlib.sha256(open(v['file'],'rb').read()).hexdigest())
assert len(set(normalized))==1,'Unexpected factorial source difference'
for a in w['available_ancestor_sources']:
 assert hashlib.sha256(open(a['file'],'rb').read()).hexdigest()==a['source_sha256']
assert hashlib.sha256(open('baseline_reference.py','rb').read()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
assert p['variants'][0]['config']['retrieval_key_source']=='content'
assert {a['knowledge_id'] for a in p['knowledge_assessments']} >= {'unirank-method-hemix','unirank-method-hyformer','unirank-method-unimixer'}
print('PASS: full used schema constraints, IDs, config/defaults, modules/imports, factorial AST, inherited methods/learned constructors, source integrity.')
